-- Kanji Adults — full install (v1.0.0)
--
-- Single self-contained migration. Creates the ten study pages, imports and
-- publishes the five SurveyJS surveys and the lab.js study, and binds them to
-- their sections. After this runs the study is complete — no CMS import or
-- section configuration is required.
--
-- Requires sh-shp-survey_js and sh-shp-lab_js to be installed first: this
-- references the `surveyJS` and `labJS` styles by name.
--
-- Idempotent — safe to re-run.
-- After running: clear the CMS cache (pages/sections).
--
-- GENERATED FILE — do not edit by hand; it is rebuilt from the study sources.

-- -----------------------------------------------------------------------
-- Asset base URL. Every image path in the lab.js study is built from this.
-- BASE_PATH in globals_untracked.php is '/' . PROJECT_NAME, so the served
-- prefix must include it. Change @base_path if this install differs.
-- -----------------------------------------------------------------------
SET @base_path  = '/selfhelp';
SET @asset_base = CONCAT(@base_path, '/assets/kanji');

-- -----------------------------------------------------------------------
-- Study identity
--
-- All nine components save into one data table, Kanji_Data, and key their row
-- on the participant code, so a run is a single row and needs no join.
--
-- The code is collected once, in part 1, and travels from page to page as a
-- path segment: each component declares `url_params`, which stores the
-- parameters it received alongside its own data, and hands them on through a
-- `redirect_at_end` template. Nothing is kept in the session, so a run is
-- resumable from the link alone and is unaffected by logging in part way.
--
-- An earlier version merged everything into one row using three hooks. They are
-- removed here, together with the plugin registration they belonged to, so an
-- existing installation upgrades cleanly.
-- -----------------------------------------------------------------------

DELETE FROM `hooks` WHERE `name` IN (
    'kanji-adults-merge-survey-row',
    'kanji-adults-merge-task-row',
    'kanji-adults-rename-columns'
);

DELETE FROM `plugins` WHERE `name` = 'kanji-adults';

-- -----------------------------------------------------------------------
-- Languages
-- The study ships German, English, French and Italian inside the surveys and
-- the lab.js task, but SelfHelp only lists a language in its picker if the
-- language exists. Without these two rows French and Italian are unreachable.
-- -----------------------------------------------------------------------

INSERT IGNORE INTO `languages` (`locale`, `language`, `csv_separator`)
    VALUES ('fr-CH', 'Français (Suisse)', ',');
INSERT IGNORE INTO `languages` (`locale`, `language`, `csv_separator`)
    VALUES ('it-CH', 'Italiano (Svizzera)', ',');

