 || \'de\');\\nlet html      = texts[lang] || texts.de;\\n// resolve {{IMG:name}} against the study\'s file pool\\nhtml = html.replace(/\\\\{\\\\{IMG:([^}]+)\\\\}\\\\}/g, (m, name) => {\\n  const src = screen.files[name];\\n  return src ? \'<img class=\\"kanji-instr-img\\" src=\\"\' + src + \'\\">\' : \'\';\\n});\\nel.querySelector(\'#instrBody\').innerHTML = html;\\nconst btn = el.querySelector(\'#instrNext\');\\nbtn.textContent = labels[lang] || labels.de;\\nbtn.addEventListener(\'click\', () => screen.respond(\'next\'));\\n"}],"parameters":[]},"c11":{"title":"Instruction instr_recall 2","type":"lab.html.Screen","content":"<div class=\\"kanji-stage kanji-instr\\"><div class=\\"kanji-instr-body\\" id=\\"instrBody\\"></div><button type=\\"button\\" class=\\"kanji-next\\" id=\\"instrNext\\"></button></div>","files":[{"localPath":"Instruktion_CJ_unsicher.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_unsicher.png"},{"localPath":"Instruktion_CJ_sicher.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_sicher.png"},{"localPath":"Instruktion_CJ_mittel.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_mittel.png"},{"localPath":"Instruktion_CJ_unsicher_EN.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_unsicher_EN.png"},{"localPath":"Instruktion_CJ_sicher_EN.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_sicher_EN.png"},{"localPath":"Instruktion_CJ_mittel_EN.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_mittel_EN.png"},{"localPath":"Instruktion_CJ_unsicher_FR.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_unsicher_FR.png"},{"localPath":"Instruktion_CJ_sicher_FR.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_sicher_FR.png"},{"localPath":"Instruktion_CJ_mittel_FR.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_mittel_FR.png"},{"localPath":"Instruktion_CJ_unsicher_IT.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_unsicher_IT.png"},{"localPath":"Instruktion_CJ_sicher_IT.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_sicher_IT.png"},{"localPath":"Instruktion_CJ_mittel_IT.png","poolPath":"{{ASSET_BASE}}/Instruktion_CJ_mittel_IT.png"}],"responses":[],"messageHandlers":[{"message":"run","code":"const screen = this;\\nconst el = this.options.el;\\nconst texts   = {\\"de\\":\\"<p>Sie werden auch gefragt, wie <b>sicher</b> Sie sich sind, dass Sie das <b>richtige Bild gewählt </b>haben. </p><p>Wenn Sie sich ganz <b>unsicher </b>sind, dann drücken Sie auf das Bild hier:</p> <p>{{IMG:Instruktion_CJ_unsicher.png}}</p> <p>Wenn Sie sich ganz<b> sicher</b> sind, drücken Sie auf dieses Bild hier:</p> <p>{{IMG:Instruktion_CJ_sicher.png}}</p> <p>Wenn Sie sich nicht ganz sicher, aber auch nicht ganz unsicher sind, nehmen Sie dieses Bild hier:</p> <p>{{IMG:Instruktion_CJ_mittel.png}}</p>\\",\\"en\\":\\"<p>You will also be asked how<b> confident </b>you are that you have <b>selected the correct image</b>. </p><p>If you are <b>unsure</b>, click on the image here:</p> <p>{{IMG:Instruktion_CJ_unsicher_EN.png}}</p> <p>If you are absolutely <b>sure</b>, click on this image here:</p> <p>{{IMG:Instruktion_CJ_sicher_EN.png}}</p> <p>If you are not entirely sure, but also not entirely unsure, take this picture here:</p> <p>{{IMG:Instruktion_CJ_mittel_EN.png}}</p>\\",\\"fr\\":\\"<p>On vous demandera &eacute;galement &agrave; quel point vous &ecirc;tes <b>s&ucirc;r(e)</b> d&rsquo;avoir <b>choisi la bonne image</b>. </p><p>Si vous n’êtes <b>pas du tout sûr(e)</b>, cliquez sur cette image:</p> <p>{{IMG:Instruktion_CJ_unsicher_FR.png}}</p> <p>Si vous êtes <b>complètement sûr(e)</b>, cliquez sur cette image:</p> <p>{{IMG:Instruktion_CJ_sicher_FR.png}}</p> <p>Si vous n’êtes ni complètement sûr(e) ni complètement incertain(e), choisissez cette image:</p> <p>{{IMG:Instruktion_CJ_mittel_FR.png}}</p>\\",\\"it\\":\\"<p> Le verr&agrave; anche chiesto quanto &egrave; <b>sicuro/a</b> di aver <b>scelto l&rsquo;immagine corretta</b>.</p><p>Se non &egrave; per <b>niente sicuro/a</b>, prema su questa immagine:</p> <p>{{IMG:Instruktion_CJ_unsicher_IT.png}}</p> <p> Se &egrave; <b>completamente sicuro/a</b>, prema su questa immagine:</p> <p>{{IMG:Instruktion_CJ_sicher_IT.png}}</p> <p> Se non &egrave; del tutto sicuro/a, ma neanche del tutto incerto/a, scelga questa immagine:</p> <p>{{IMG:Instruktion_CJ_mittel_IT.png}}</p>\\"};\\nconst labels  = {\\"de\\":\\"Weiter\\",\\"en\\":\\"Next\\",\\"fr\\":\\"Suivant\\",\\"it\\":\\"Avanti\\"};\\nconst lang    = (window.KANJI_LANG || (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\').match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'de\');\\nlet html      = texts[lang] || texts.de;\\n// resolve {{IMG:name}} against the study\'s file pool\\nhtml = html.replace(/\\\\{\\\\{IMG:([^}]+)\\\\}\\\\}/g, (m, name) => {\\n  const src = screen.files[name];\\n  return src ? \'<img class=\\"kanji-instr-img\\" src=\\"\' + src + \'\\">\' : \'\';\\n});\\nel.querySelector(\'#instrBody\').innerHTML = html;\\nconst btn = el.querySelector(\'#instrNext\');\\nbtn.textContent = labels[lang] || labels.de;\\nbtn.addEventListener(\'click\', () => screen.respond(\'next\'));\\n"}],"parameters":[]},"c12":{"title":"Instruction instr_recall 3","type":"lab.html.Screen","content":"<div class=\\"kanji-stage kanji-instr\\"><div class=\\"kanji-instr-body\\" id=\\"instrBody\\"></div><button type=\\"button\\" class=\\"kanji-next\\" id=\\"instrNext\\"></button></div>","files":[],"responses":[],"messageHandlers":[{"message":"run","code":"const screen = this;\\nconst el = this.options.el;\\nconst texts   = {\\"de\\":\\"<p><b>Sie werden die Aufgabe nun einmal üben können. </b></p>\\",\\"en\\":\\"<p><b>You will now be able to practice the task. </b></p>\\",\\"fr\\":\\"<p><b>Vous allez maintenant pouvoir vous entra&icirc;ner &agrave; l&rsquo;exercice une fois.</b></p>\\",\\"it\\":\\"<p> <b>Ora potr&agrave; esercitarsi con il compito una volta.</b> </p>\\"};\\nconst labels  = {\\"de\\":\\"Weiter\\",\\"en\\":\\"Next\\",\\"fr\\":\\"Suivant\\",\\"it\\":\\"Avanti\\"};\\nconst lang    = (window.KANJI_LANG || (((document.querySelector(\'