,"files":[],"responses":[],"messageHandlers":[],"parameters":[]},"c17":{"title":"Save practice","type":"lab.html.Screen","content":"<div class=\\"kanji-stage\\"><p class=\\"kanji-wait\\">…</p></div>","timeout":"50","messageHandlers":[{"message":"after:end","code":"if (!this.options.datastore || typeof labJSFields === \'undefined\') { return; }\\nconst extra = { block: \'practice\' };\\nconst qChoice = \'Q22\';\\nconst qConf   = \'Q23\';\\nif (qChoice) {\\n  const rows = (this.options.datastore.data || []).filter(\\n    r => r.sender === \'Recall trial\' && r.confidence !== undefined\\n  );\\n  const trials = rows.map((r, i) => {\\n    const t = { trial: i + 1, item: r.concept };\\n    t[\'Auswahl_\' + qChoice]               = r.chosen_img;\\n    t[\'Auswahl_\' + qConf]                 = r.confidence;\\n    t[\'Reaktionszeit_\' + qChoice + \'_ms\'] = r.rt_choice;\\n    t[\'Reaktionszeit_\' + qConf + \'_ms\']   = r.rt_confidence;\\n    t[\'Reaktionszeit_\' + qConf + \'_ab_\' + qChoice + \'_ms\'] = r.rt_conf_from_choice;\\n    t.korrekt       = r.correct;\\n    t.korrekt_seite = r.correct_side;\\n    t.gewaehlt      = r.chosen_side;\\n    t.orig_pos      = r.orig_pos;\\n    return t;\\n  });\\n  // One JSON column per block, plus the totals worth filtering on.\\n  extra[\'trials_\' + \'practice\'] = trials;\\n  extra[\'n_trials_\' + \'practice\']  = trials.length;\\n  extra[\'n_correct_\' + \'practice\'] = trials.filter(t => t.korrekt === 1).length;\\n}\\nif (!qChoice) {\\n  const lernSender = \'\';\\n  const lernRows = (this.options.datastore.data || []).filter(\\n    r => r.lern_item !== undefined && r.sender === lernSender\\n  );\\n  if (lernRows.length) {\\n    extra[\'trials_\' + \'practice\'] = lernRows.map((r, i) => ({\\n      trial: i + 1, item: r.lern_item,\\n      dauer_ms: (r.time_show === undefined || r.time_end === undefined)\\n        ? null : Math.round(r.time_end - r.time_show)\\n    }));\\n    extra[\'n_trials_\' + \'practice\'] = lernRows.length;\\n  }\\n}\\nconst dataStore = this.options.datastore;\\nextra.trigger_type       = \'updated\';\\nextra.labjs_response_id  = labjs_response_id;\\nextra.labjs_generated_id = labJSFields[\'labjs_generated_id\'];\\nif (labJSFields[\'extra_params\']) {\\n  for (const p in labJSFields[\'extra_params\']) {\\n    extra[\'extra_param_\' + p] = labJSFields[\'extra_params\'][p];\\n  }\\n}\\nextra.UserLanguage = (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\')\\n  .match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'\';\\nextra.UserLanguage = extra.UserLanguage ? extra.UserLanguage.toUpperCase() : \'\';\\nconst redirectTo = (typeof resolveRedirectAtEnd === \'function\')\\n  ? resolveRedirectAtEnd(labJSFields[\'redirect_at_end\'], extra, labJSFields[\'base_path\'])\\n  : labJSFields[\'redirect_at_end\'];\\nconst go = () => {\\n  if (extra.trigger_type === \'finished\' && redirectTo) { window.location.href = redirectTo; }\\n};\\nPromise.resolve(dataStore.transmit(\'#\', extra)).then(go, go);\\n"}],"files":[],"responses":[],"parameters":[]},"c18":{"title":"Instruction start_learn_A 1","type":"lab.html.Screen","content":"<div class=\\"kanji-stage kanji-instr\\"><div class=\\"kanji-instr-body\\" id=\\"instrBody\\"></div><button type=\\"button\\" class=\\"kanji-next\\" id=\\"instrNext\\"></button></div>","files":[{"localPath":"aufmerksamkeit_4_gluehbirne.png","poolPath":"{{ASSET_BASE}}/aufmerksamkeit_4_gluehbirne.png"}],"responses":[],"messageHandlers":[{"message":"run","code":"const screen = this;\\nconst el = this.options.el;\\nconst texts   = {\\"de\\":\\"<b>Wir starten jetzt mit der Lernaufgabe.</b> <ul> <li>Sie werden zwei Runden der Lernaufgabe lösen. In jeder Runde werden Sie 30 Kanjis lernen. </li> <li>Zwischendurch gibt es kleine Pausen. In diesen dürfen Sie kurze Fragen zu Ihrer Familie beantworten. </li> <li>Machen Sie sich keine Sorgen, wenn Sie Fehler machen. Fehler sind normal. Wir wollen die Fehler sehen, weil sie für unsere Forschung wichtig sind.</li> </ul> <p>{{IMG:aufmerksamkeit_4_gluehbirne.png}}</p>\\",\\"en\\":\\"<b>We will now begin with the learning task.</b> <ul> <li>You will complete two rounds of the learning task. In each round, you will learn 30 kanji characters.</li> <li>There will be short breaks in between. During these breaks, you will answer brief questions about your family.</li> <li>Don&#39;t worry if you make mistakes. Mistakes are normal. We want to observe the mistakes because they are important for our research. </li> </ul> <p>{{IMG:aufmerksamkeit_4_gluehbirne.png}}</p>\\",\\"fr\\":\\"<p data-end=\\\\\\"162\\\\\\" data-start=\\\\\\"96\\\\\\"> <b>Nous allons maintenant commencer l&rsquo;exercice d&rsquo;apprentissage.</b></p> <ul> <li data-end=\\\\\\"162\\\\\\" data-start=\\\\\\"96\\\\\\">Vous allez r&eacute;aliser deux s&eacute;ries de l&rsquo;exercice d&rsquo;apprentissage. Dans chaque s&eacute;rie, vous apprendrez 30 kanjis.</li> <li data-end=\\\\\\"162\\\\\\" data-start=\\\\\\"96\\\\\\">Entre les s&eacute;ries, il y aura de courtes pauses. Pendant ces pauses, vous pourrez r&eacute;pondre &agrave; quelques questions sur votre famille.</li> <li data-end=\\\\\\"162\\\\\\" data-start=\\\\\\"96\\\\\\">Ne vous inqui&eacute;tez pas si vous faites des erreurs. Les erreurs sont normales. Nous voulons les voir, car elles sont importantes pour notre recherche.</li> </ul> <p>{{IMG:aufmerksamkeit_4_gluehbirne.png}}</p>\\",\\"it\\":\\"<p data-end=\\\\\\"94\\\\\\" data-start=\\\\\\"47\\\\\\"><b>Ora iniziamo il compito di apprendimento.</b></p> <ul> <li data-end=\\\\\\"94\\\\\\" data-start=\\\\\\"47\\\\\\">Affronter&agrave; due serie del compito di apprendimento. In ogni serie imparer&agrave; 30 kanji.</li> <li data-end=\\\\\\"94\\\\\\" data-start=\\\\\\"47\\\\\\">Ci saranno brevi pause tra le serie. Durante queste pause potr&agrave; rispondere a brevi domande sulla sua famiglia.</li> <li data-end=\\\\\\"94\\\\\\" data-start=\\\\\\"47\\\\\\">Non si preoccupi se commette degli errori. Gli errori sono normali. Vogliamo osservarli perch&eacute; sono importanti per la nostra ricerca.</li> </ul> <p>{{IMG:aufmerksamkeit_4_gluehbirne.png}}</p>\\"};\\nconst labels  = {\\"de\\":\\"Weiter\\",\\"en\\":\\"Next\\",\\"fr\\":\\"Suivant\\",\\"it\\":\\"Avanti\\"};\\nconst lang    = (window.KANJI_LANG || (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\').match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'de\');\\nlet html      = texts[lang] || texts.de;\\n// resolve {{IMG:name}} against the study\'s file pool\\nhtml = html.replace(/\\\\{\\\\{IMG:([^}]+)\\\\}\\\\}/g, (m, name) => {\\n  const src = screen.files[name];\\n  return src ? \'<img class=\\"kanji-instr-img\\" src=\\"\' + src + \'\\">\' : \'\';\\n});\\nel.querySelector(\'#instrBody\').innerHTML = html;\\nconst btn = el.querySelector(\'#instrNext\');\\nbtn.textContent = labels[lang] || labels.de;\\nbtn.addEventListener(\'click\', () => screen.respond(\'next\'));\\n"}],"parameters":[]},"c19":{"title":"Learn A stimulus","type":"lab.html.Screen","content":"<div class=\\"kanji-stage kanji-pair\\"><img class=\\"kanji-item\\" src=\\"${ this.files[this.parameters.kanji_img] }\\"><img class=\\"kanji-item\\" src=\\"${ this.files[this.parameters.meaning_img] }\\"></div>","timeout":"5000","files":[{"localPath":"Fixationskreuz.jpg","poolPath":"{{ASSET_BASE}}/Fixationskreuz.jpg"},{"localPath":"Herbst_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Herbst_Kanji.jpg"},{"localPath":"Herbst.jpg","poolPath":"{{ASSET_BASE}}/Herbst.jpg"},{"localPath":"Ast_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Ast_Kanji.jpg"},{"localPath":"Ast.jpg","poolPath":"{{ASSET_BASE}}/Ast.jpg"},{"localPath":"Baumwolle_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Baumwolle_Kanji.jpg"},{"localPath":"Baumwolle.jpg","poolPath":"{{ASSET_BASE}}/Baumwolle.jpg"},{"localPath":"Pflanze_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Pflanze_Kanji.jpg"},{"localPath":"Pflanze.jpg","poolPath":"{{ASSET_BASE}}/Pflanze.jpg"},{"localPath":"Welt_Kanji.jpg","poolPath":"{{