= this.options.el;\\nconst pageStart = performance.now();\\nconst lang = (window.KANJI_LANG || (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\').match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'de\');\\nconst sfx = { de: \'\', en: \'_EN\', fr: \'_FR\', it: \'_IT\' }[lang] || \'\';\\nel.querySelectorAll(\'[data-cj-img]\').forEach(img => {\\n  const src = screen.files[img.getAttribute(\'data-cj-img\') + sfx + \'.png\'];\\n  if (src) img.src = src;\\n});\\nlet answerLockTs = null;\\n\\n// Select-then-confirm within one group. `onLock` fires on the\\n// second click of the same option, matching the original.\\nconst bindGroup = (root, onLock) => {\\n  const opts = Array.from(root.querySelectorAll(\'.kanji-opt\'));\\n  let locked = false;\\n  opts.forEach(opt => {\\n    opt.addEventListener(\'click\', () => {\\n      if (locked) return;\\n      if (opt.classList.contains(\'selected\')) {\\n        opt.classList.remove(\'selected\');\\n        opt.classList.add(\'locked\');\\n        locked = true;\\n        root.classList.add(\'is-locked\');\\n        onLock(opt);\\n      } else {\\n        opts.forEach(o => o.classList.remove(\'selected\'));\\n        opt.classList.add(\'selected\');\\n      }\\n    });\\n  });\\n};\\n\\nconst choices    = el.querySelector(\'#kanjiChoices\');\\nconst confidence = el.querySelector(\'#kanjiConfidence\');\\n\\nbindGroup(choices, (opt) => {\\n  const side = opt.getAttribute(\'data-side\');\\n  answerLockTs = performance.now();\\n  screen.data.chosen_side  = side;\\n  screen.data.chosen_img   = side === \'left\' ? screen.parameters.left_img : screen.parameters.right_img;\\n  screen.data.correct_side = screen.parameters.correct_side;\\n  screen.data.correct      = side === screen.parameters.correct_side ? 1 : 0;\\n  screen.data.rt_choice    = Math.round(answerLockTs - pageStart);\\n  confidence.hidden = false;\\n});\\n\\nbindGroup(confidence, (opt) => {\\n  const now = performance.now();\\n  screen.data.confidence        = parseInt(opt.getAttribute(\'data-cj\'), 10);\\n  screen.data.rt_confidence     = Math.round(now - pageStart);\\n  screen.data.rt_conf_from_choice = answerLockTs === null ? null : Math.round(now - answerLockTs);\\n  // The original waits 300 ms after the confidence lock before advancing.\\n  setTimeout(() => screen.respond(String(screen.data.confidence)), 300);\\n});\\n"}],"parameters":[]},"c27":{"title":"Fixation","type":"lab.html.Screen","content":"<div class=\\"kanji-stage\\"><img class=\\"kanji-fix\\" src=\\"${ this.files[\'Fixationskreuz.jpg\'] }\\"></div>","timeout":"500","files":[{"localPath":"Fixationskreuz.jpg","poolPath":"{{ASSET_BASE}}/Fixationskreuz.jpg"},{"localPath":"Herbst_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Herbst_Kanji.jpg"},{"localPath":"Herbst.jpg","poolPath":"{{ASSET_BASE}}/Herbst.jpg"},{"localPath":"Ast_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Ast_Kanji.jpg"},{"localPath":"Ast.jpg","poolPath":"{{ASSET_BASE}}/Ast.jpg"},{"localPath":"Baumwolle_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Baumwolle_Kanji.jpg"},{"localPath":"Baumwolle.jpg","poolPath":"{{ASSET_BASE}}/Baumwolle.jpg"},{"localPath":"Pflanze_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Pflanze_Kanji.jpg"},{"localPath":"Pflanze.jpg","poolPath":"{{ASSET_BASE}}/Pflanze.jpg"},{"localPath":"Welt_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Welt_Kanji.jpg"},{"localPath":"Welt.jpg","poolPath":"{{ASSET_BASE}}/Welt.jpg"},{"localPath":"Stock_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Stock_Kanji.jpg"},{"localPath":"Stock.jpg","poolPath":"{{ASSET_BASE}}/Stock.jpg"},{"localPath":"Zeit_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Zeit_Kanji.jpg"},{"localPath":"Zeit.jpg","poolPath":"{{ASSET_BASE}}/Zeit.jpg"},{"localPath":"Dunkelheit_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Dunkelheit_Kanji.jpg"},{"localPath":"Dunkelheit.jpg","poolPath":"{{ASSET_BASE}}/Dunkelheit.jpg"},{"localPath":"Nebel_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Nebel_Kanji.jpg"},{"localPath":"Nebel.jpg","poolPath":"{{ASSET_BASE}}/Nebel.jpg"},{"localPath":"Wal