onst extra = { block: \'learn_B\' };\\nconst qChoice = \'\';\\nconst qConf   = \'\';\\nif (qChoice) {\\n  const rows = (this.options.datastore.data || []).filter(\\n    r => r.sender === \'Recall trial\' && r.confidence !== undefined\\n  );\\n  const trials = rows.map((r, i) => {\\n    const t = { trial: i + 1, item: r.concept };\\n    t[\'Auswahl_\' + qChoice]               = r.chosen_img;\\n    t[\'Auswahl_\' + qConf]                 = r.confidence;\\n    t[\'Reaktionszeit_\' + qChoice + \'_ms\'] = r.rt_choice;\\n    t[\'Reaktionszeit_\' + qConf + \'_ms\']   = r.rt_confidence;\\n    t[\'Reaktionszeit_\' + qConf + \'_ab_\' + qChoice + \'_ms\'] = r.rt_conf_from_choice;\\n    t.korrekt       = r.correct;\\n    t.korrekt_seite = r.correct_side;\\n    t.gewaehlt      = r.chosen_side;\\n    t.orig_pos      = r.orig_pos;\\n    return t;\\n  });\\n  // One JSON column per block, plus the totals worth filtering on.\\n  extra[\'trials_\' + \'learn_B\'] = trials;\\n  extra[\'n_trials_\' + \'learn_B\']  = trials.length;\\n  extra[\'n_correct_\' + \'learn_B\'] = trials.filter(t => t.korrekt === 1).length;\\n}\\nif (!qChoice) {\\n  const lernSender = \'Learn B stimulus\';\\n  const lernRows = (this.options.datastore.data || []).filter(\\n    r => r.lern_item !== undefined && r.sender === lernSender\\n  );\\n  if (lernRows.length) {\\n    extra[\'trials_\' + \'learn_B\'] = lernRows.map((r, i) => ({\\n      trial: i + 1, item: r.lern_item,\\n      dauer_ms: (r.time_show === undefined || r.time_end === undefined)\\n        ? null : Math.round(r.time_end - r.time_show)\\n    }));\\n    extra[\'n_trials_\' + \'learn_B\'] = lernRows.length;\\n  }\\n}\\nconst dataStore = this.options.datastore;\\nextra.trigger_type       = \'finished\';\\nextra.labjs_response_id  = labjs_response_id;\\nextra.labjs_generated_id = labJSFields[\'labjs_generated_id\'];\\nif (labJSFields[\'extra_params\']) {\\n  for (const p in labJSFields[\'extra_params\']) {\\n    extra[\'extra_param_\' + p] = labJSFields[\'extra_params\'][p];\\n  }\\n}\\nextra.UserLanguage = (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\')\\n  .match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'\';\\nextra.UserLanguage = extra.UserLanguage ? extra.UserLanguage.toUpperCase() : \'\';\\nconst redirectTo = (typeof resolveRedirectAtEnd === \'function\')\\n  ? resolveRedirectAtEnd(labJSFields[\'redirect_at_end\'], extra, labJSFields[\'base_path\'])\\n  : labJSFields[\'redirect_at_end\'];\\nconst go = () => {\\n  if (extra.trigger_type === \'finished\' && redirectTo) { window.location.href = redirectTo; }\\n};\\nPromise.resolve(dataStore.transmit(\'#\', extra)).then(go, go);\\n"}],"files":[],"responses":[],"parameters":[]},"root":{"title":"Kanji Adults (seg3)","type":"lab.flow.Sequence","children":["c31","c32","c36","c37"],"files":[],"responses":[],"messageHandlers":[],"parameters":[]}},"files":{"files":{"{{ASSET_BASE}}/Fixationskreuz.jpg":{"content":"{{ASSET_BASE}}/Fixationskreuz.jpg"},"{{ASSET_BASE}}/Herbst_Kanji.jpg":{"content":"{{ASSET_BASE}}/Herbst_Kanji.jpg"},"{{ASSET_BASE}}/Herbst.jpg":{"content":"{{ASSET_BASE}}/Herbst.jpg"},"{{ASSET_BASE}}/Ast_Kanji.jpg":{"content":"{{ASSET_BASE}}/Ast_Kanji.jpg"},"{{ASSET_BASE}}/Ast.jpg":{"content":"{{ASSET_BASE}}/Ast.jpg"},"{{ASSET_BASE}}/Baumwolle_Kanji.jpg":{"content":"{{ASSET_BASE}}/Baumwolle_Kanji.jpg"},"{{ASSET_BASE}}/Baumwolle.jpg":{"content":"{{ASSET_BASE}}/Baumwolle.jpg"},"{{ASSET_BASE}}/Pflanze_Kanji.jpg":{"content":"{{ASSET_BASE}}/Pflanze_Kanji.jpg"},"{{ASSET_BASE}}/Pflanze.jpg":{"content":"{{ASSET_BASE}}/Pflanze.jpg"},"{{ASSET_BASE}}/Welt_Kanji.jpg":{"content":"{{ASSET_BASE}}/Welt_Kanji.jpg"},"{{ASSET_BASE}}/Welt.jpg":{"content":"{{ASSET_BASE}}/Welt.jpg"},"{{ASSET_BASE}}/Stock_Kanji.jpg":{"content":"{{ASSET_BASE}}/Stock_Kanji.jpg"},"{{ASSET_BASE}}/Stock.jpg":{"content":"{{ASSET_BASE}}/Stock.jpg"},"{{ASSET_BASE}}/Zeit_Kanji.jpg":{"content":"{{ASSET_BASE}}/Zeit_Kanji.jpg"},"{{ASSET_BASE}}/Zeit.jpg":{"content":"{{ASSET_B