meters":[]},"c43":{"title":"Recall B","type":"lab.flow.Loop","children":["c42"],"templateParameters":{"columns":[{"name":"list","type":"string"},{"name":"trial","type":"string"},{"name":"concept","type":"string"},{"name":"kanji_img","type":"string"},{"name":"correct_img","type":"string"},{"name":"distractor_img","type":"string"},{"name":"orig_pos","type":"string"},{"name":"left_img","type":"string"},{"name":"right_img","type":"string"},{"name":"correct_side","type":"string"}],"rows":[["B","1","Palme","Palme_Kanji.jpg","Palme.jpg","Strand.jpg","1","Palme.jpg","Strand.jpg","left"],["B","2","Bakterium","Bakterium_Kanji.jpg","Bakterium.jpg","Sueden.jpg","1","Bakterium.jpg","Sueden.jpg","left"],["B","3","Huegel","Huegel_Kanji.jpg","Huegel.jpg","Rechts.jpg","1","Huegel.jpg","Rechts.jpg","left"],["B","4","Schnee","Schnee_Kanji.jpg","Schnee.jpg","Regen.jpg","1","Schnee.jpg","Regen.jpg","left"],["B","5","Wolke","Wolke_Kanji.jpg","Wolke.jpg","Winter.jpg","1","Wolke.jpg","Winter.jpg","left"]]},"shuffle":true,"files":[],"responses":[],"messageHandlers":[],"parameters":[]},"c44":{"title":"Instruction ende 1","type":"lab.html.Screen","content":"<div class=\\"kanji-stage kanji-instr\\"><div class=\\"kanji-instr-body\\" id=\\"instrBody\\"></div><button type=\\"button\\" class=\\"kanji-next\\" id=\\"instrNext\\"></button></div>","files":[{"localPath":"00_ablenkung_konfetti_luftb.png","poolPath":"{{ASSET_BASE}}/00_ablenkung_konfetti_luftb.png"}],"responses":[],"messageHandlers":[{"message":"run","code":"const screen = this;\\nconst el = this.options.el;\\nconst texts   = {\\"de\\":\\"<p><b> </b></p><p><b>Sie haben nun alle Kanjis gelernt! Vielen Dank!</b></p> <p> Drücken Sie weiter, um zum Schluss der Lernaufgabe zu gelangen. </p> <p>{{IMG:00_ablenkung_konfetti_luftb.png}}</p>\\",\\"en\\":\\"<p><b> </b></p><p><b>You have now learned all the kanji! Thank you very much!</b> Press the button to proceed to the end of the learning task.</p> <p>{{IMG:00_ablenkung_konfetti_luftb.png}}</p>\\",\\"fr\\":\\"<p> <p data-end=\\\\\\"124\\\\\\" data-start=\\\\\\"56\\\\\\"><b> </b></p><p data-end=\\\\\\"124\\\\\\" data-start=\\\\\\"56\\\\\\"><b>Vous avez maintenant appris tous les kanjis! Merci beaucoup!</b> Cliquez sur Continuer pour accéder à la fin de l’exercice d’apprentissage.</p> </p> <p>{{IMG:00_ablenkung_konfetti_luftb.png}}</p>\\",\\"it\\":\\"<p> <p data-start=\\\\\\"47\\\\\\" data-end=\\\\\\"93\\\\\\"><b> </b></p><p data-start=\\\\\\"47\\\\\\" data-end=\\\\\\"93\\\\\\"><b>Ha imparato tutti i kanji! Grazie mille!</b> Clicchi su Continua per arrivare alla fine del compito di apprendimento.</p> </p> <p>{{IMG:00_ablenkung_konfetti_luftb.png}}</p>\\"};\\nconst labels  = {\\"de\\":\\"Weiter\\",\\"en\\":\\"Next\\",\\"fr\\":\\"Suivant\\",\\"it\\":\\"Avanti\\"};\\nconst lang    = (window.KANJI_LANG || (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\').match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'de\');\\nlet html      = texts[lang] || texts.de;\\n// resolve {{IMG:name}} against the study\'s file pool\\nhtml = html.replace(/\\\\{\\\\{IMG:([^}]+)\\\\}\\\\}/g, (m, name) => {\\n  const src = screen.files[name];\\n  return src ? \'<img class=\\"kanji-instr-img\\" src=\\"\' + src + \'\\">\' : \'\';\\n});\\nel.querySelector(\'#instrBody\').innerHTML = html;\\nconst btn = el.querySelector(\'#instrNext\');\\nbtn.textContent = labels[lang] || labels.de;\\nbtn.addEventListener(\'click\', () => screen.respond(\'next\'));\\n"}],"parameters":[]},"c45":{"title":"Save recall_B","type":"lab.html.Screen","content":"<div class=\\"kanji-stage\\"><p class=\\"kanji-wait\\">…</p></div>","timeout":"50","messageHandlers":[{"message":"after:end","code":"if (!this.options.datastore || typeof labJSFields === \'undefined\') { return; }\\nconst extra = { block: \'recall_B\' };\\nconst qChoice = \'Q2\';\\nconst qConf   = \'Q3\';\\nif (qChoice) {\\n  const rows = (this.options.datastore.data || []).filter(\\n    r => r.sender === \'Recall trial\' && r.confidence !== undefined\\n  );\\n  const trials = rows.map((r, i) => {\\n    const t = { trial: i + 1, item: r.concept };\\n    t[\'Auswahl_\' + qChoice]               = r.chosen_img;\\n    t[\'Auswahl_\' + qConf]                 = r.confidence;\\n    t[\'Reaktionszeit_\' + qChoice + \'_ms\'] = r.rt_choice;\\n    t[\'Reaktionszeit_\' + qConf + \'_ms\']   = r.rt_confidence;\\n    t[\'Reaktionszeit_\' + qConf + \'_ab_\' + qChoice + \'_ms\'] = r.rt_conf_from_choice;\\n    t.korrekt       = r.correct;\\n    t.korrekt_seite = r.correct_side;\\n    t.gewaehlt      = r.chosen_side;\\n    t.orig_pos      = r.orig_pos;\\n    return t;\\n  });\\n  // One JSON column per block, plus the totals worth filtering on.\\n  extra[\'trials_\' + \'recall_B\'] = trials;\\n  extra[\'n_trials_\' + \'recall_B\']  = trials.length;\\n  extra[\'n_correct_\' + \'recall_B\'] = trials.filter(t => t.korrekt === 1).length;\\n}\\nif (!qChoice) {\\n  const lernSender = \'\';\\n  const lernRows = (this.options.datastore.data || []).filter(\\n    r => r.lern_item !== undefined && r.sender === lernSender\\n  );\\n  if (lernRows.length) {\\n    extra[\'trials_\' + \'recall_B\'] = lernRows.map((r, i) => ({\\n      trial: i + 1, item: r.lern_item,\\n      dauer_ms: (r.time_show === undefined || r.time_end === undefined)\\n        ? null : Math.round(r.time_end - r.time_show)\\n    }));\\n    extra[\'n_trials_\' + \'recall_B\'] = lernRows.length;\\n  }\\n}\\nconst dataStore = this.options.datastore;\\nextra.trigger_type       = \'finished\';\\nextra.labjs_response_id  = labjs_response_id;\\nextra.labjs_generated_id = labJSFields[\'labjs_generated_id\'];\\nif (labJSFields[\'extra_params\']) {\\n  for (const p in labJSFields[\'extra_params\']) {\\n    extra[\'extra_param_\' + p] = labJSFields[\'extra_params\'][p];\\n  }\\n}\\nextra.UserLanguage = (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\')\\n  .match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'\';\\nextra.UserLanguage = extra.UserLanguage ? extra.UserLanguage.toUpperCase() : \'\';\\nconst redirectTo = (typeof resolveRedirectAtEnd === \'function\')\\n  ? resolveRedirectAtEnd(labJSFields[\'redirect_at_end\'], extra, labJSFields[\'base_path\'])\\n  : labJSFields[\'redirect_at_end\'];\\nconst go = () => {\\n  if (extra.trigger_type === \'finished\' && redirectTo) { window.location.href = redirectTo; }\\n};\\nPromise.resolve(dataStore.transmit(\'#\', extra)).then(go, go);\\n"}],"files":[],"responses":[],"parameters":[]},"root":{"title":"Kanji Adults (seg4)","type":"lab.flow.Sequence","children":["c38","c39","c43","c44","c45"],"files":[],"responses":[],"messageHandlers":[],"parameters":[]}},"files":{"files":{"{{ASSET_BASE}}/Fixationskreuz.jpg":{"content":"{{ASSET_BASE}}/Fixationskreuz.jpg"},"{{ASSET_BASE}}/Herbst_Kanji.jpg":{"content":"{{ASSET_BASE}}/Herbst_Kanji.jpg"},"{{ASSET_BASE}}/Herbst.jpg":{"content":"{{ASSET_BASE}}/Herbst.jpg"},"{{ASSET_BASE}}/Ast_Kanji.jpg":{"content":"{{ASSET_BASE}}/Ast_Kanji.jpg"},"{{ASSET_BASE}}/Ast.jpg":{"content":"{{ASSET_BASE}}/Ast.jpg"},"{{ASSET_BASE}}/Baumwolle_Kanji.jpg":{"content":"{{ASSET_BASE}}/Baumwolle_Kanji.jpg"},"{{ASSET_BASE}}/Baumwolle.jpg":{"content":"{{ASSET_BASE}}/Baumwolle.jpg"},"{{ASSET_BASE}}/Pflanze_Kanji.jpg":{"content":"{{ASSET_BASE}}/Pflanze_Kanji.jpg"},"{{ASSET_BASE}}/Pflanze.jpg":{"content":"{{ASSET_BASE}}/Pflanze.jpg"},"{{ASSET_BASE}}/Welt_Kanji.jpg":{"content":"{{ASSET_BASE}}/Welt_Kanji.jpg"},"{{ASSET_BASE}}/Welt.jpg":{"content":"{{ASSET_BASE}}/Welt.jpg"},"{{ASSET_BASE}}/Stock_Kanji.jpg":{"content":"{{ASSET_BASE}}/Stock_Kanji.jpg"},"{{ASSET_BASE}}/Stock.jpg":{"content":"{{ASSET_BASE}}/Stock.jpg"},"{{ASSET_BASE}}/Zeit_Kanji.jpg":{"content":"{{ASSET_BASE}}/Zeit_Kanji.jpg"},"{{ASSET_BASE}}/Zeit.jpg":{"content":"{{ASSET_BASE}}/Zeit.jpg"},"{{ASSET_BASE}}/Dunkelheit_Kanji.jpg":{"content":"{{ASSET_BASE}}/Dunkelheit_Kanji.jpg"},"{{ASSET_BASE}}/Dunkelheit.jpg":{"content":"{{ASSET_BASE}}/Dunkelheit.jpg"},"{{ASSET_BASE}}/Nebel_Kanji.jpg":{